export function geometryPath(g,geometry,project){g.beginPath();for(const poly of geometry.type==='MultiPolygon'?geometry.coordinates:[geometry.coordinates])for(const ring of poly){ring.forEach((p,i)=>{const v=project(p);i?g.lineTo(...v):g.moveTo(...v);});g.closePath();}}
