  const c=this.surface?this.surface(pixels+4,pixels+4):document.createElement('canvas');c.width=c.height=pixels+4;const g=c.getContext('2d');g.setTransform(resolution,0,0,resolution,2-x*size*resolution,2-y*size*resolution);g.imageSmoothingEnabled=true;g.imageSmoothingQuality='high';g.fillStyle=MAP_PALETTE.ground;g.fillRect(x*size-bleed,y*size-bleed,size+bleed*2,size+bleed*2);
