  for(const f of fs)paintSurface(this,g,f,view,resolution);
  for(const f of fs.filter(f=>f.tags.waterway)){this.path(g,f);g.lineCap='round';g.lineJoin='round';const river=f.tags.waterway==='river';g.strokeStyle='#b4d5b4';g.lineWidth=river?20:10;g.stroke();g.strokeStyle='#70b7bc';g.lineWidth=river?14:6;g.stroke();g.strokeStyle='#b5e0d3a0';g.lineWidth=river?4:1.5;g.stroke();}
  const roads=fs.filter(f=>f.tags.highway&&!['construction','proposed'].includes(f.tags.highway)&&(resolution>=.5||!['service','footway','path','steps','track','cycleway'].includes(f.tags.highway))).sort((a,b)=>this.width(b)-this.width(a));
