  for(const f of roads.filter(f=>f.tags.name&&resolution>=1)){if(labelled.has(f.tags.name))continue;let a,b,best=0;for(let i=1;i<f.points.length;i++){const p=f.points[i-1],q=f.points[i],d=Math.hypot(p[0]-q[0],p[1]-q[1]);if(d>best){best=d;a=p;b=q;}}if(best<90)continue;labelled.add(f.tags.name);let angle=Math.atan2(b[1]-a[1],b[0]-a[0]);if(Math.abs(angle)>Math.PI/2)angle+=Math.PI;g.save();g.translate((a[0]+b[0])/2,(a[1]+b[1])/2);g.rotate(angle);g.font='11px NanumRound,sans-serif';g.strokeStyle='#f3ecd6';g.lineWidth=4;g.strokeText(f.tags.name,0,0);g.fillStyle='#65765d';g.fillText(f.tags.name,0,0);g.restore();}
