  const minX=Math.max(0,Math.floor(a[0]/size)),maxX=Math.min(Math.ceil(w.max[0]/size)-1,Math.floor(b[0]/size)),minY=Math.max(0,Math.floor(a[1]/size)),maxY=Math.min(Math.ceil(w.max[1]/size)-1,Math.floor(b[1]/size));
  this.cacheLimit=Math.max(64,(maxX-minX+1)*(maxY-minY+1)+16);this.visibleKeys=new Set();for(let tx=minX;tx<=maxX;tx++)for(let ty=minY;ty<=maxY;ty++)this.visibleKeys.add(resolution+':'+tx+','+ty);
