  if(w.route.length){g.beginPath();[w.position,...w.route].forEach((p,i)=>{const v=[ox+p[0]*scale,oy+p[1]*scale];i?g.lineTo(...v):g.moveTo(...v);});g.lineWidth=large?2.5:1.4;g.strokeStyle='#dc9240';g.stroke();}
